from s1_ui import add

# v126–v126.1: Cappadocia's charter contracts at NAV · Nevşehir Airport: three agency owners (Seoul, Shanghai, Istanbul)
# in their own voice, the late plane, the airport's shuttle sign, Albuquerque's short first-offer scene. Braces are
# filled in by the app: {n} people, {d} first day, {e} last day, {p} price per head, {r} the rival.

CAST = {
 "jiwoo": ("Han Ji-woo", "Ji-woo", "ハン・ジウ", "ジウ", "한지우", "지우",
           ("Owner of Haneul Wings, Seoul", "Haneul Wings sahibi, Seul", "Inhaberin von Haneul Wings, Seoul", "Dueña de Haneul Wings, Seúl",
            "ハヌル・ウィングス代表（ソウル）", "하늘 윙스 대표, 서울")),
 "chen": ("Chen Hao", "Chen", "チェン・ハオ", "チェン", "천하오", "천하오",
          ("Founder of Pearl Bund Travel, Shanghai", "Pearl Bund Travel kurucusu, Şanghay", "Gründer von Pearl Bund Travel, Shanghai", "Fundador de Pearl Bund Travel, Shanghái",
           "パール・バンド・トラベル創業者（上海）", "펄 번드 트래블 창업자, 상하이")),
 "murat": ("Murat Bey", "Murat", "ムラト・ベイ", "ムラト", "무라트 베이", "무라트",
           ("Owner of Haliç Gündoğumu Turları, Istanbul", "Haliç Gündoğumu Turları sahibi, İstanbul", "Inhaber von Haliç Gündoğumu Turları, Istanbul",
            "Dueño de Haliç Gündoğumu Turları, Estambul", "ハリチ・ギュンドウム・トゥルラル社長（イスタンブール）", "할리치 귄도우무 투르라르 대표, 이스탄불")),
}
for k, (name, short, ja, jaS, ko, koS, title) in CAST.items():
    add(f"ctr.{k}.name", name, name, name, name, ja, ko)
    add(f"ctr.{k}.short", short, short, short, short, jaS, koS)
    add(f"ctr.{k}.title", *title)

def lines(owner, d):
    for line, t in d.items():
        add(f"ctr.{owner}.{line}", *t)

